  // AI-generated START - 加载模版列表
  /// 从 API 加载模版列表
  Future<void> loadTemplates() async {
    _isLoading = true;
    _error = null;
    _hasMore = true;
    _cursor = '';
    notifyListeners();

    try {
      //真实API调用（已注释）
      final request = MPGetTemplateListRequest(
        pageSize: 20,
        cursor: _cursor,
      );
      final response = await mp_template_api.getTemplateList(request);
      if (response == null) {
        _error = '获取模版列表失败';
        _templates = [];
        return;
      }
      // 检查响应状态
      if (response.baseResp.code != 0) {
        _error = response.baseResp.message;
        _templates = [];
      } else {
        // 根据后台返回的数据结构创建 CardItem 列表
        _templates = <CardItem>[];

        // 1. 最近使用的模板（如果有）
        if (response.recentTemplate != null) {
          _templates.add(CardItem(
            title: '最近使用',
            items: [
              _convertToHorizontalScrollItem(response.recentTemplate!),
            ],
          ));
        }

        // 2. 推荐模板
        if (response.recommendTemplates.isNotEmpty) {
          _templates.add(CardItem(
            title: '推荐模板',
            items: response.recommendTemplates.map((template) => _convertToHorizontalScrollItem(template)).toList(),
          ));
        }

        // 3. 自定义模板
        final customTemplateItems = response.customTemplates
            .map((template) => _convertToHorizontalScrollItem(template, isMyTemplate: true))
            .toList();

        // 添加"创建模板"项到自定义模板列表的开头
        customTemplateItems.insert(
            0,
