  // AI-generated START - 转换数据模型
  /// 将 MPTemplateStruct 转换为 HorizontalScrollTemplateItem
  HorizontalScrollTemplateItem _convertToHorizontalScrollItem(
    MPTemplateStruct template, {
    bool isMyTemplate = false,
  }) {
    // 优先使用 template.icon 作为网络图片URL
    // 如果没有 template.icon，则使用默认图标和颜色
    final iconUrl = template.icon;
    IconData? iconData;
    Color? iconColor;

    if (iconUrl == null || iconUrl.isEmpty) {
      // 如果没有 icon URL，使用默认图标和颜色
      iconData = _getIconForTemplate(template.title ?? '');
      iconColor = _getColorForTemplate(template.title ?? '');
    }

    return HorizontalScrollTemplateItem(
      id: template.id ?? '',
      title: template.title ?? '',
      imageUrl: iconUrl,
      icon: iconData,
      iconColor: iconColor,
      backgroundColor: Colors.white,
      isMyTemplate: isMyTemplate,
    );
  }
  // AI-generated END - 转换数据模型

  // AI-generated START - 获取图标
  /// 根据模版标题获取对应的图标
  IconData _getIconForTemplate(String title) {
    if (title.contains('会议') || title.contains('会议纪要')) {
      return Icons.people;
    } else if (title.contains('项目') || title.contains('项目总结')) {
      return Icons.assessment;
    } else if (title.contains('学习') || title.contains('笔记')) {
      return Icons.menu_book;
    } else if (title.contains('面试')) {
      return Icons.person_outline;
    } else if (title.contains('通话') || title.contains('摘要')) {
      return Icons.phone;
    } else {
      return Icons.description; // 默认图标
    }
  }
  // AI-generated END - 获取图标

  // AI-generated START - 获取颜色
  /// 根据模版标题获取对应的颜色
  Color _getColorForTemplate(String title) {
    if (title.contains('会议') || title.contains('会议纪要')) {
      return const Color(0xFF64B5F6); // 浅蓝色
    } else if (title.contains('项目') || title.contains('项目总结')) {
      return const Color(0xFF81C784); // 绿色
    } else if (title.contains('学习') || title.contains('笔记')) {
      return const Color(0xFFBA68C8); // 紫色
    } else if (title.contains('面试')) {
      return const Color(0xFF9575CD); // 浅紫色
    } else if (title.contains('通话') || title.contains('摘要')) {
      return const Color(0xFF22C55E); // 绿色
    } else {
      return const Color(0xFF9CA3AF); // 默认灰色
    }
  }
  // AI-generated END - 获取颜色

  // AI-generated START - 选择模版
  void selectTemplate(int cardIndex, int itemIndex) {
    if (cardIndex >= 0 && cardIndex < _templates.length) {
      final card = _templates[cardIndex];
      if (itemIndex >= 0 && itemIndex < card.items.length) {
        _selectedIndex = cardIndex;
        notifyListeners();
      }
    }
  }
  // AI-generated END - 选择模版

  // AI-generated START - 添加模版
  void addTemplate(CardItem template) {
