  // AI-generated START - 加载更多模版
  /// 加载更多模版数据
  Future<void> loadMoreTemplates() async {
    if (_isLoading || !_hasMore) return;

    _isLoading = true;
    notifyListeners();

    try {
      // 调用 API 加载更多模版数据
      final request = MPGetTemplateListRequest(
