      if (response != null) {
        if (response.baseResp.code != 0) {
          debugPrint('加载更多模版失败: ${response.baseResp.message}');
        } else {
          // 根据后台返回的数据结构创建 CardItem 列表并追加
          final moreCardItems = <CardItem>[];

          // 1. 最近使用的模板（如果有）
          if (response.recentTemplate != null) {
            moreCardItems.add(CardItem(
