              ],
            ));
          }

          // 2. 推荐模板
          if (response.recommendTemplates.isNotEmpty) {
            moreCardItems.add(CardItem(
              title: '推荐模板',
              items: response.recommendTemplates.map((template) => _convertToHorizontalScrollItem(template)).toList(),
            ));
          }

          // 3. 自定义模板
          final moreCustomTemplateItems = response.customTemplates
              .map((template) => _convertToHorizontalScrollItem(template, isMyTemplate: true))
              .toList();

          // 添加"创建模板"项到自定义模板列表的开头
          moreCustomTemplateItems.insert(
              0,
              const HorizontalScrollTemplateItem(
                id: 'create_template',
                title: '创建模板',
                isCreateItem: true,
              ));

          moreCardItems.add(CardItem(
            title: '自定义模板',
            items: moreCustomTemplateItems,
          ));

          // 4. templates map 中的模板（按 key 分组）
          if (response.templates.isNotEmpty) {
            // 遍历 Map，将 key 作为 title，value（List）作为 items
            response.templates.forEach((key, templatesList) {
              if (templatesList.isNotEmpty) {
                final templateItems =
                    templatesList.map((template) => _convertToHorizontalScrollItem(template)).toList();
                moreCardItems.add(CardItem(
                  title: key, // 使用 Map 的 key 作为 title
                  items: templateItems, // 使用 Map 的 value（List）作为 items
                ));
              }
            });
          }

          _templates.addAll(moreCardItems);
          _hasMore = response.hasMore;
          // 更新游标
          if (moreCardItems.isNotEmpty && moreCardItems.last.items.isNotEmpty) {
            _cursor = moreCardItems.last.items.last.title;
          }
        }
      } else {
        debugPrint('加载更多模版失败: 响应为空');
